package com.yongdrel.payment_proof_service.adapter.in.web;
import com.yongdrel.payment_proof_service.application.service.PaymentProofService;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.UUID;
@RestController @RequestMapping("/internal/payment-proofs") public class InternalProofReferenceController{private final PaymentProofService s;private final byte[] key;public InternalProofReferenceController(PaymentProofService s,@Value("${app.internal.api-key}")String k){if(k==null||k.isBlank())throw new IllegalStateException("Proof key required");this.s=s;key=k.getBytes(StandardCharsets.UTF_8);}@GetMapping("/verify-reference")public boolean verify(@RequestParam UUID orderId,@RequestParam UUID tenantId,@RequestParam String reference,@RequestHeader(value="X-Internal-API-Key",required=false)String provided){if(provided==null||!MessageDigest.isEqual(key,provided.getBytes(StandardCharsets.UTF_8)))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid internal credentials");return s.verifyReference(orderId,tenantId,reference);}}
